// CAMADA REPOSITORY: só sabe GUARDAR e BUSCAR dados. Não conhece regras de
// negócio, não calcula nada — é o "arquivo de pedidos" da aplicação.
export function criarRepositorioPedidos() {
  const registros = []; // o "banco" mora aqui, protegido de quem está de fora

  return {
    listar() {
      // Devolve uma CÓPIA: quem chamou pode mexer sem corromper o arquivo.
      return [...registros];
    },

    buscarPorId(id) {
      const achado = registros.find((pedido) => pedido.id === id);
      return achado === undefined ? null : achado;
    },

    salvar(pedido) {
      if (typeof pedido !== 'object' || pedido === null) {
        throw new Error('pedido precisa ser um objeto');
      }
      registros.push(pedido);
      return pedido;
    },
  };
}

