// CAMADA SERVICE: concentra as REGRAS DE NEGÓCIO. Não sabe onde os pedidos
// são guardados — o repositório chega pronto por INJEÇÃO DE DEPENDÊNCIA.
export function criarServiceDePedidos(repositorio) {
  if (
    typeof repositorio?.salvar !== 'function' ||
    typeof repositorio?.listar !== 'function'
  ) {
    throw new Error('service precisa receber um repositório com salvar e listar');
  }

  let proximoId = 1; // regra de negócio: ids são sequenciais, começando em 1

  return {
    registrarPedido({ produto, quantidade, precoUnitario } = {}) {
      if (typeof produto !== 'string' || produto.trim() === '') {
        throw new Error('produto precisa ser um texto não vazio');
      }
      if (!Number.isInteger(quantidade) || quantidade < 1) {
        throw new Error('quantidade precisa ser um inteiro maior ou igual a 1');
      }
      if (typeof precoUnitario !== 'number' || precoUnitario < 0) {
        throw new Error('precoUnitario precisa ser um número maior ou igual a 0');
      }

      const pedido = {
        id: proximoId,
        produto,
        quantidade,
        precoUnitario,
        total: quantidade * precoUnitario,
      };
      proximoId += 1;

      repositorio.salvar(pedido); // só entrega ao repositório: não sabe onde mora
      return pedido;
    },

    listarPedidos() {
      return repositorio.listar();
    },

    totalDeTudo() {
      return repositorio.listar().reduce((soma, pedido) => soma + pedido.total, 0);
    },
  };
}

