import { criarRepositorioPedidos } from './repository.mjs';
import { criarServiceDePedidos } from './service.mjs';

// CAMADA FACTORY: o ponto de montagem do app. Recebe uma configuração opcional
// e devolve o app PRONTO — com o repositório real ou com um fake (testes).
export function criarAppDePedidos(opcoes = {}) {
  const repositorio = opcoes.repositorio ?? criarRepositorioPedidos();
  const service = criarServiceDePedidos(repositorio);
  return { repositorio, service };
}

