import { test } from 'node:test';
import assert from 'node:assert/strict';
import { criarRepositorioPedidos } from './lib/repository.mjs';
import { criarServiceDePedidos } from './lib/service.mjs';
import { criarAppDePedidos } from './lib/factory.mjs';

test('factory monta o app completo com repositório real', () => {
  const app = criarAppDePedidos();
  const pedido = app.service.registrarPedido({ produto: 'Café', quantidade: 2, precoUnitario: 8 });
  assert.deepEqual(pedido, { id: 1, produto: 'Café', quantidade: 2, precoUnitario: 8, total: 16 });
  assert.equal(app.repositorio.listar().length, 1); // o service salvou no repositório do app
});

test('DI: a factory aceita um repositório fake para testes', () => {
  const fake = {
    salvos: [],
    salvar(pedido) { this.salvos.push(pedido); },
    listar() { return this.salvos; },
  };
  const app = criarAppDePedidos({ repositorio: fake });
  assert.equal(app.repositorio, fake); // o fake foi usado, não o repositório real
  const pedido = app.service.registrarPedido({ produto: 'Bolo', quantidade: 1, precoUnitario: 10 });
  assert.equal(fake.salvos.length, 1);
  assert.equal(fake.salvos[0].id, pedido.id);
  assert.equal(app.service.totalDeTudo(), 10);
});

test('regras de negócio vivem no service e nada inválido chega ao repositório', () => {
  const fake = {
    salvos: [],
    salvar(pedido) { this.salvos.push(pedido); },
    listar() { return this.salvos; },
  };
  const service = criarServiceDePedidos(fake);
  assert.throws(() => service.registrarPedido({ produto: '', quantidade: 1, precoUnitario: 8 }));
  assert.throws(() => service.registrarPedido({ produto: 'Café', quantidade: 0, precoUnitario: 8 }));
  assert.throws(() => service.registrarPedido({ produto: 'Café', quantidade: 1, precoUnitario: -1 }));
  assert.equal(fake.salvos.length, 0);
});

test('repository sozinho: salvar, buscar, listar com cópia e recusas', () => {
  const repositorio = criarRepositorioPedidos();
  repositorio.salvar({ id: 5, produto: 'Café' });
  assert.deepEqual(repositorio.buscarPorId(5), { id: 5, produto: 'Café' });
  assert.equal(repositorio.buscarPorId(99), null);
  const lista = repositorio.listar();
  lista.push({ id: 6, produto: 'Bolo' });
  assert.equal(repositorio.listar().length, 1); // a lista devolvida era uma cópia
  assert.throws(() => repositorio.salvar('não é objeto'));
});

test('ids sequenciais e totalDeTudo somando os pedidos', () => {
  const app = criarAppDePedidos();
  app.service.registrarPedido({ produto: 'Café', quantidade: 2, precoUnitario: 8 });
  app.service.registrarPedido({ produto: 'Bolo', quantidade: 1, precoUnitario: 12.5 });
  const terceiro = app.service.registrarPedido({ produto: 'Suco', quantidade: 3, precoUnitario: 5 });
  assert.equal(terceiro.id, 3);
  assert.equal(app.service.totalDeTudo(), 16 + 12.5 + 15);
});

test('o service valida o repositório que recebe (contrato da DI)', () => {
  const valido = criarServiceDePedidos({ salvar() {}, listar() { return []; } });
  assert.equal(typeof valido.registrarPedido, 'function');
  assert.throws(() => criarServiceDePedidos({}));
  assert.throws(() => criarServiceDePedidos(null));
});
